"use client";

import { motion } from "framer-motion";
import { 
  Users, 
  Mail, 
  CheckCircle, 
  Wallet, 
  PenTool, 
  FilePlus, 
  ClipboardList, 
  MessageCircle, 
  UserCheck, 
  Settings 
} from "lucide-react";

// === KOMPONEN KARTU STATISTIK (FIXED ICON) ===
const StatCard = ({ title, value, icon: Icon, color, delay }: any) => (
  <motion.div 
    initial={{ opacity: 0, y: 20 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ delay }}
    className="relative group p-6 rounded-3xl bg-white dark:bg-[#0f172a]/50 border border-slate-200 dark:border-white/5 hover:border-blue-500 dark:hover:border-white/10 transition-all overflow-hidden shadow-lg dark:shadow-none"
  >
    {/* ICON BACKGROUND (WATERMARK) - DIPERBAIKI */}
    <div className={`absolute -right-6 -bottom-6 opacity-5 group-hover:opacity-10 transition-opacity text-${color}-500`}>
       {/* Ganti scale dengan size manual biar ga kepotong aneh */}
       <Icon size={120} strokeWidth={1.5} />
    </div>
    
    <div className="relative z-10">
      <div className={`w-12 h-12 rounded-2xl bg-${color}-100 dark:bg-${color}-500/20 flex items-center justify-center text-${color}-600 dark:text-${color}-400 mb-4`}>
        <Icon size={24} />
      </div>
      <h3 className="text-slate-500 dark:text-slate-400 text-xs font-bold uppercase tracking-widest mb-1">{title}</h3>
      <p className="text-3xl font-black text-slate-800 dark:text-white">{value}</p>
    </div>

    {/* Glow Line */}
    <div className={`absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-${color}-500 to-transparent opacity-50`} />
  </motion.div>
);

export default function AdminDashboard() {
  return (
    <div className="space-y-10">
      
      {/* HEADER WELCOME */}
      <div className="flex flex-col md:flex-row justify-between items-end gap-4 border-b border-slate-200 dark:border-white/5 pb-8">
         <div>
            <h1 className="text-3xl md:text-4xl font-black text-slate-800 dark:text-white mb-2">
              Command Center 🛸
            </h1>
            <p className="text-slate-500 dark:text-slate-400">Selamat datang kembali, Kapten. Berikut laporan hari ini.</p>
         </div>
         <div className="text-right">
            <p className="text-xs font-bold text-blue-500 uppercase tracking-widest">System Status</p>
            <div className="flex items-center gap-2 justify-end">
               <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
               <span className="text-slate-700 dark:text-white font-mono text-sm">ONLINE - v2.0</span>
            </div>
         </div>
      </div>

      {/* STATS GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
         <StatCard title="Total Siswa" value="1,240" icon={Users} color="blue" delay={0.1} />
         <StatCard title="Aspirasi Baru" value="18" icon={Mail} color="purple" delay={0.2} />
         <StatCard title="Proker Selesai" value="85%" icon={CheckCircle} color="green" delay={0.3} />
         <StatCard title="Dana Kas" value="Rp 12jt" icon={Wallet} color="yellow" delay={0.4} />
      </div>

      {/* RECENT ACTIVITY */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         
         {/* LEFT: Quick Actions */}
         <motion.div 
           initial={{ opacity: 0, x: -20 }}
           animate={{ opacity: 1, x: 0 }}
           transition={{ delay: 0.5 }}
           className="lg:col-span-2 bg-white dark:bg-[#0f172a]/50 border border-slate-200 dark:border-white/5 rounded-3xl p-8 shadow-lg dark:shadow-none"
         >
            <h3 className="text-slate-800 dark:text-white font-bold text-lg mb-6 flex items-center gap-2">
               <PenTool size={18} className="text-blue-500" /> Akses Cepat
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
               {[
                 { label: 'Tulis Berita', icon: PenTool },
                 { label: 'Buat Proker', icon: FilePlus },
                 { label: 'Cek Laporan', icon: ClipboardList },
                 { label: 'Broadcast WA', icon: MessageCircle },
                 { label: 'Data Alumni', icon: UserCheck },
                 { label: 'Settings', icon: Settings }
               ].map((item, i) => (
                  <button key={i} className="p-4 rounded-xl bg-slate-50 dark:bg-white/5 hover:bg-blue-600 dark:hover:bg-blue-600 hover:text-white border border-slate-200 dark:border-white/5 hover:border-blue-500 transition-all text-slate-500 dark:text-slate-400 text-sm font-bold text-left group">
                     <item.icon size={20} className="mb-2 text-blue-500 group-hover:text-white transition-colors" />
                     {item.label}
                  </button>
               ))}
            </div>
         </motion.div>

         {/* RIGHT: Recent Aspirasi */}
         <motion.div 
           initial={{ opacity: 0, x: 20 }}
           animate={{ opacity: 1, x: 0 }}
           transition={{ delay: 0.6 }}
           className="bg-white dark:bg-[#0f172a]/50 border border-slate-200 dark:border-white/5 rounded-3xl p-8 shadow-lg dark:shadow-none"
         >
            <h3 className="text-slate-800 dark:text-white font-bold text-lg mb-6 flex items-center gap-2">
               <Mail size={18} className="text-purple-500" /> Aspirasi Terbaru
            </h3>
            <div className="space-y-4">
               {[
                 { name: "Ahmad (X RPL)", msg: "WC di lantai 2 tolong diperbaiki airnya...", time: "2m lalu" },
                 { name: "Siti (XI TKJ)", msg: "Request lagu buat pensi besok dong!", time: "1j lalu" },
                 { name: "Anonim", msg: "Parkiran motor makin sempit min.", time: "3j lalu" },
               ].map((item, i) => (
                 <div key={i} className="p-4 rounded-xl bg-slate-50 dark:bg-white/5 border border-slate-100 dark:border-white/5 flex gap-3 items-start">
                    <div className="w-2 h-2 mt-1.5 rounded-full bg-blue-500 flex-shrink-0" />
                    <div>
                       <p className="text-slate-900 dark:text-white text-sm font-bold">{item.name}</p>
                       <p className="text-slate-500 dark:text-slate-400 text-xs mt-1 line-clamp-2">"{item.msg}"</p>
                       <p className="text-slate-400 dark:text-slate-600 text-[10px] mt-2">{item.time}</p>
                    </div>
                 </div>
               ))}
               <button className="w-full py-3 mt-2 rounded-xl border border-slate-200 dark:border-white/10 text-xs font-bold text-slate-500 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-white/5 transition-colors">
                  Lihat Semua Aspirasi →
               </button>
            </div>
         </motion.div>

      </div>

    </div>
  );
}